#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> printVertically(std::string s) {
        std::vector<std::string> words;
        std::stringstream ss(s);
        std::string w;
        int maxLen = 0;
        while (ss >> w) {
            maxLen = std::max(maxLen, (int)w.size());
            words.push_back(w);
        }
        std::vector<std::string> res;
        for (int c = 0; c < maxLen; ++c) {
            std::string col = "";
            for (const auto& word : words) {
                col += (c < (int)word.size()) ? word[c] : ' ';
            }
            while (!col.empty() && col.back() == ' ') col.pop_back();
            res.push_back(col);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<String> printVertically(String s) {
        String[] words = s.split(" ");
        int maxLen = 0;
        for (String w : words) maxLen = Math.max(maxLen, w.length());
        List<String> res = new ArrayList<>();
        for (int c = 0; c < maxLen; c++) {
            StringBuilder sb = new StringBuilder();
            for (String w : words) {
                sb.append(c < w.length() ? w.charAt(c) : ' ');
            }
            int end = sb.length() - 1;
            while (end >= 0 && sb.charAt(end) == ' ') end--;
            res.add(sb.substring(0, end + 1));
        }
        return res;
    }
}

var printVertically = function(s) {
    const words = s.split(" ");
    let maxLen = 0;
    for (const w of words) if (w.length > maxLen) maxLen = w.length;
    const res = [];
    for (let c = 0; c < maxLen; c++) {
        let col = "";
        for (const w of words) {
            col += (c < w.length) ? w[c] : " ";
        }
        res.push(col.trimEnd());
    }
    return res;
};
